// The glyph cache (ADR 0057): exact glyphs rasterized by FreeType at the
// drawn size, and multi-channel distance fields generated by msdfgen on the
// job system, packed into fixed-size pages on shelves. A full set of pages
// gets another, up to a limit; past it, the least recently used page not
// used this frame is cleared whole.

#include "TextInternal.h"

#include <crucible/HashMap.h>
#include <crucible/Jobs.h>

#include <ft2build.h>
#include FT_FREETYPE_H
#include FT_OUTLINE_H
#include <msdfgen.h>

#include <algorithm>
#include <cmath>
#include <cstring>

namespace crucible::text {

namespace {

struct GlyphKey
{
    uint64_t font; // Font::serial
    uint32_t glyph;
    uint32_t size; // 26.6 physical pixels; 0 for distance fields
    GlyphRendering rendering;

    bool operator==(const GlyphKey&) const = default;
};

struct GlyphKeyHash
{
    uint64_t operator()(const GlyphKey& key) const
    {
        const uint64_t mixed = key.font * 0x9e3779b97f4a7c15ull ^ (uint64_t{key.glyph} << 32 | key.size) ^
                               static_cast<uint64_t>(key.rendering) << 63;
        return Hash<uint64_t>()(mixed);
    }
};

struct Entry
{
    CachedGlyph glyph{};
    bool ready = false; // false while its distance field generates
};

struct Shelf
{
    uint32_t y, height, x;
};

struct Page
{
    Vector<uint8_t> pixels{MemoryTag::Text};
    Vector<Shelf> shelves{MemoryTag::Text};
    Vector<GlyphKey> keys{MemoryTag::Text}; // what's on it, to forget when it's cleared
    uint32_t nextShelf = 0;                 // y of the next shelf
    uint64_t lastUsed = 0;
    uint32_t changedX0 = 0, changedY0 = 0, changedX1 = 0, changedY1 = 0; // empty when x0 == x1
};

// A distance field being generated: the outline goes in, the texels come
// out, and the main thread places them once its job is done.
struct PendingField
{
    GlyphKey key{};
    msdfgen::Shape shape;
    double unitsPerEm = 0;
    jobs::JobCounter counter;
    Vector<uint8_t> texels{MemoryTag::Text}; // RGBA8, rows down
    uint32_t width = 0, height = 0;
    float left = 0, top = 0; // ems
};

struct Kind
{
    Vector<Page*> pages{MemoryTag::Text};
    uint32_t maxPages;
    uint32_t bytesPerTexel;
};

struct Cache
{
    HashMap<GlyphKey, Entry, GlyphKeyHash> entries{MemoryTag::Text};
    Kind exact{.maxPages = maxExactPages, .bytesPerTexel = 1};
    Kind fields{.maxPages = maxDistanceFieldPages, .bytesPerTexel = 4};
    Vector<PendingField*> pending{MemoryTag::Text};
    uint64_t frame = 1;
    uint32_t evictions = 0;
    uint64_t exactMade = 0;
    uint64_t fieldsMade = 0;
};

Cache cache;

Kind& kindOf(GlyphRendering rendering)
{
    return rendering == GlyphRendering::Exact ? cache.exact : cache.fields;
}

bool placeOnPage(Page& page, uint32_t width, uint32_t height, uint32_t& x, uint32_t& y)
{
    const uint32_t w = width + glyphPadding;
    const uint32_t h = height + glyphPadding;
    // The shelf that wastes the least height, among those it fits.
    Shelf* best = nullptr;
    for (Shelf& shelf : page.shelves)
    {
        if (shelf.height >= h && shelf.x + w <= glyphPageSize && (best == nullptr || shelf.height < best->height))
        {
            best = &shelf;
        }
    }
    // A much taller shelf wastes too much: start one that fits, if there's room.
    if ((best == nullptr || best->height > h * 2) && page.nextShelf + h <= glyphPageSize && w <= glyphPageSize)
    {
        page.shelves.pushBack({page.nextShelf, h, 0});
        page.nextShelf += h;
        best = &page.shelves.back();
    }
    if (best == nullptr)
    {
        return false;
    }
    x = best->x;
    y = best->y;
    best->x += w;
    return true;
}

void clearPage(Page& page)
{
    for (const GlyphKey& key : page.keys)
    {
        cache.entries.erase(key);
    }
    page.keys.clear();
    page.shelves.clear();
    page.nextShelf = 0;
    std::memset(page.pixels.data(), 0, page.pixels.size());
    page.changedX0 = 0;
    page.changedY0 = 0;
    page.changedX1 = glyphPageSize;
    page.changedY1 = glyphPageSize;
}

// Finds room for an image: on a page with space, a new page, or the least
// recently used page not used this frame, cleared.
bool allocate(Kind& kind, uint32_t width, uint32_t height, uint32_t& page, uint32_t& x, uint32_t& y)
{
    for (uint32_t i = 0; i < kind.pages.size(); ++i)
    {
        if (placeOnPage(*kind.pages[i], width, height, x, y))
        {
            page = i;
            return true;
        }
    }
    if (kind.pages.size() < kind.maxPages)
    {
        auto* added = create<Page>(MemoryTag::Text);
        added->pixels.resize(size_t{glyphPageSize} * glyphPageSize * kind.bytesPerTexel);
        std::memset(added->pixels.data(), 0, added->pixels.size());
        kind.pages.pushBack(added);
        page = static_cast<uint32_t>(kind.pages.size()) - 1;
        return placeOnPage(*added, width, height, x, y);
    }
    uint32_t oldest = UINT32_MAX;
    for (uint32_t i = 0; i < kind.pages.size(); ++i)
    {
        if (kind.pages[i]->lastUsed < cache.frame &&
            (oldest == UINT32_MAX || kind.pages[i]->lastUsed < kind.pages[oldest]->lastUsed))
        {
            oldest = i;
        }
    }
    if (oldest == UINT32_MAX)
    {
        return false;
    }
    clearPage(*kind.pages[oldest]);
    ++cache.evictions;
    page = oldest;
    return placeOnPage(*kind.pages[oldest], width, height, x, y);
}

void markChanged(Page& page, uint32_t x, uint32_t y, uint32_t width, uint32_t height)
{
    if (page.changedX0 == page.changedX1)
    {
        page.changedX0 = x;
        page.changedY0 = y;
        page.changedX1 = x + width;
        page.changedY1 = y + height;
        return;
    }
    page.changedX0 = std::min(page.changedX0, x);
    page.changedY0 = std::min(page.changedY0, y);
    page.changedX1 = std::max(page.changedX1, x + width);
    page.changedY1 = std::max(page.changedY1, y + height);
}

// Stores an image (rows down, `bytesPerTexel` each) as a glyph's entry. An
// empty image needs no room. False when there is no room this frame.
bool store(const GlyphKey& key, const uint8_t* texels, uint32_t width, uint32_t height, uint32_t pitch, float left,
           float top, Entry& entry)
{
    Kind& kind = kindOf(key.rendering);
    entry.glyph = {0, 0, 0, static_cast<uint16_t>(width), static_cast<uint16_t>(height), left, top};
    if (width == 0 || height == 0)
    {
        entry.glyph.width = 0;
        entry.glyph.height = 0;
        entry.ready = true;
        return true;
    }
    uint32_t pageIndex, x, y;
    if (width + glyphPadding > glyphPageSize || height + glyphPadding > glyphPageSize ||
        !allocate(kind, width, height, pageIndex, x, y))
    {
        return false;
    }
    Page& page = *kind.pages[pageIndex];
    const uint32_t rowBytes = width * kind.bytesPerTexel;
    for (uint32_t row = 0; row < height; ++row)
    {
        std::memcpy(&page.pixels[(size_t{y + row} * glyphPageSize + x) * kind.bytesPerTexel], texels + row * pitch,
                    rowBytes);
    }
    markChanged(page, x, y, width, height);
    page.keys.pushBack(key);
    page.lastUsed = cache.frame;
    entry.glyph.page = pageIndex;
    entry.glyph.x = static_cast<uint16_t>(x);
    entry.glyph.y = static_cast<uint16_t>(y);
    entry.ready = true;
    return true;
}

// ---------------------------------------------------------------------------
// Distance fields
// ---------------------------------------------------------------------------

struct Outline
{
    msdfgen::Shape* shape;
    msdfgen::Contour* contour;
    msdfgen::Point2 position;
};

msdfgen::Point2 pointOf(const FT_Vector* v)
{
    return {static_cast<double>(v->x), static_cast<double>(v->y)};
}

int moveTo(const FT_Vector* to, void* user)
{
    auto& outline = *static_cast<Outline*>(user);
    outline.contour = &outline.shape->addContour();
    outline.position = pointOf(to);
    return 0;
}

int lineTo(const FT_Vector* to, void* user)
{
    auto& outline = *static_cast<Outline*>(user);
    const msdfgen::Point2 point = pointOf(to);
    outline.contour->addEdge(msdfgen::EdgeHolder(outline.position, point));
    outline.position = point;
    return 0;
}

int conicTo(const FT_Vector* control, const FT_Vector* to, void* user)
{
    auto& outline = *static_cast<Outline*>(user);
    const msdfgen::Point2 point = pointOf(to);
    outline.contour->addEdge(msdfgen::EdgeHolder(outline.position, pointOf(control), point));
    outline.position = point;
    return 0;
}

int cubicTo(const FT_Vector* a, const FT_Vector* b, const FT_Vector* to, void* user)
{
    auto& outline = *static_cast<Outline*>(user);
    const msdfgen::Point2 point = pointOf(to);
    outline.contour->addEdge(msdfgen::EdgeHolder(outline.position, pointOf(a), pointOf(b), point));
    outline.position = point;
    return 0;
}

constexpr FT_Outline_Funcs outlineFunctions{moveTo, lineTo, conicTo, cubicTo, 0, 0};

// On a worker: the field around the outline, distanceFieldEm texels per
// em, with distanceFieldRange texels of margin.
void generateField(void* data)
{
    auto& field = *static_cast<PendingField*>(data);
    msdfgen::Shape& shape = field.shape;
    if (shape.contours.empty())
    {
        return; // no outline: an empty image
    }
    shape.normalize();
    msdfgen::edgeColoringSimple(shape, 3.0);
    const msdfgen::Shape::Bounds bounds = shape.getBounds();
    const double scale = distanceFieldEm / field.unitsPerEm; // texels per font unit
    const double range = distanceFieldRange / scale;         // font units
    const auto width = static_cast<uint32_t>(std::ceil((bounds.r - bounds.l) * scale + 2 * distanceFieldRange));
    const auto height = static_cast<uint32_t>(std::ceil((bounds.t - bounds.b) * scale + 2 * distanceFieldRange));
    const msdfgen::Vector2 translate(range - bounds.l, range - bounds.b);
    msdfgen::Bitmap<float, 3> bitmap(static_cast<int>(width), static_cast<int>(height));
    const msdfgen::SDFTransformation transformation(msdfgen::Projection(scale, translate), msdfgen::Range(range));
    msdfgen::generateMSDF(bitmap, shape, transformation);
    msdfgen::distanceSignCorrection(bitmap, shape, transformation, msdfgen::FILL_NONZERO);

    field.texels.resize(size_t{width} * height * 4);
    for (uint32_t row = 0; row < height; ++row)
    {
        for (uint32_t column = 0; column < width; ++column)
        {
            // msdfgen's rows go up; the page's go down.
            const float* distances = bitmap(static_cast<int>(column), static_cast<int>(height - 1 - row));
            uint8_t* texel = &field.texels[(size_t{row} * width + column) * 4];
            for (int channel = 0; channel < 3; ++channel)
            {
                texel[channel] = static_cast<uint8_t>(std::lround(std::clamp(distances[channel], 0.0f, 1.0f) * 255));
            }
            texel[3] = 255;
        }
    }
    field.width = width;
    field.height = height;
    field.left = static_cast<float>(-translate.x / field.unitsPerEm);
    field.top = static_cast<float>(-(height / scale - translate.y) / field.unitsPerEm);
}

void queueField(Font& font, const GlyphKey& key)
{
    auto* field = create<PendingField>(MemoryTag::Text);
    field->key = key;
    field->unitsPerEm = font.unitsPerEm;
    // The outline is read here: a FreeType face is for one thread at a time.
    if (FT_Load_Glyph(font.face, key.glyph, FT_LOAD_NO_SCALE | FT_LOAD_NO_HINTING) == 0 &&
        font.face->glyph->format == FT_GLYPH_FORMAT_OUTLINE)
    {
        Outline outline{&field->shape, nullptr, {}};
        FT_Outline_Decompose(&font.face->glyph->outline, &outlineFunctions, &outline);
    }
    cache.pending.pushBack(field);
    const jobs::Job job{generateField, field};
    jobs::run({&job, 1}, jobs::JobPriority::Background, field->counter);
}

// Places finished fields; with `wait`, waits for every one first.
void collectFields(bool wait)
{
    for (size_t i = 0; i < cache.pending.size();)
    {
        PendingField* field = cache.pending[i];
        if (wait)
        {
            jobs::wait(field->counter);
        }
        if (field->counter.remaining.load(std::memory_order_acquire) != 0)
        {
            ++i;
            continue;
        }
        Entry* entry = cache.entries.find(field->key);
        if (entry != nullptr && !store(field->key, field->texels.data(), field->width, field->height, field->width * 4,
                                       field->left, field->top, *entry))
        {
            if (!wait)
            {
                ++i; // no room this frame: try again next frame
                continue;
            }
            cache.entries.erase(field->key);
        }
        ++cache.fieldsMade;
        destroy(MemoryTag::Text, field);
        cache.pending.removeSwap(i);
    }
}

} // namespace

const CachedGlyph* cachedGlyph(Font& font, uint32_t glyph, GlyphRendering rendering, float pixelSize)
{
    const bool exact = rendering == GlyphRendering::Exact;
    const GlyphKey key{font.serial, glyph, exact ? static_cast<uint32_t>(std::lround(pixelSize * 64)) : 0, rendering};
    if (Entry* found = cache.entries.find(key))
    {
        if (!found->ready)
        {
            return nullptr;
        }
        if (found->glyph.width != 0)
        {
            kindOf(rendering).pages[found->glyph.page]->lastUsed = cache.frame;
        }
        return &found->glyph;
    }
    if (!exact)
    {
        cache.entries.insertOrAssign(key, Entry{});
        queueField(font, key);
        return nullptr;
    }

    // Light hinting: outlines move only vertically, so advances (and the
    // shaper's positions) stay true.
    FT_FaceRec_* face = sizedFace(font, key.size);
    if (key.size == 0 || FT_Load_Glyph(face, glyph, FT_LOAD_TARGET_LIGHT) != 0 ||
        FT_Render_Glyph(face->glyph, FT_RENDER_MODE_LIGHT) != 0)
    {
        Entry empty{};
        empty.ready = true;
        return &cache.entries.insertOrAssign(key, empty).glyph;
    }
    const FT_Bitmap& bitmap = face->glyph->bitmap;
    Entry entry{};
    if (!store(key, bitmap.buffer, bitmap.width, bitmap.rows, static_cast<uint32_t>(std::abs(bitmap.pitch)),
               static_cast<float>(face->glyph->bitmap_left), -static_cast<float>(face->glyph->bitmap_top), entry))
    {
        return nullptr; // every page is in use this frame
    }
    ++cache.exactMade;
    return &cache.entries.insertOrAssign(key, entry).glyph;
}

void updateGlyphCache()
{
    collectFields(false);
    ++cache.frame;
}

void finishGlyphs()
{
    collectFields(true);
}

uint32_t glyphPageCount(GlyphRendering rendering)
{
    return static_cast<uint32_t>(kindOf(rendering).pages.size());
}

GlyphPage glyphPage(GlyphRendering rendering, uint32_t page)
{
    const Kind& kind = kindOf(rendering);
    if (page >= kind.pages.size())
    {
        return {};
    }
    const Page& p = *kind.pages[page];
    return {p.pixels.data(), kind.bytesPerTexel,        p.changedX0,
            p.changedY0,     p.changedX1 - p.changedX0, p.changedY1 - p.changedY0};
}

void clearGlyphChanges(GlyphRendering rendering, uint32_t page)
{
    Kind& kind = kindOf(rendering);
    if (page < kind.pages.size())
    {
        Page& p = *kind.pages[page];
        p.changedX0 = p.changedX1 = p.changedY0 = p.changedY1 = 0;
    }
}

GlyphCacheStats glyphCacheStats()
{
    return {static_cast<uint32_t>(cache.entries.size()), static_cast<uint32_t>(cache.pending.size()), cache.evictions,
            cache.exactMade, cache.fieldsMade};
}

void clearGlyphCache()
{
    collectFields(true);
    for (Kind* kind : {&cache.exact, &cache.fields})
    {
        for (Page* page : kind->pages)
        {
            destroy(MemoryTag::Text, page);
        }
        kind->pages.clear();
    }
    cache.entries.clear();
    cache.frame = 1;
    cache.evictions = 0;
    cache.exactMade = 0;
    cache.fieldsMade = 0;
}

} // namespace crucible::text
